query.base:
TS metrics-gcp.bigquery.otel-*
// Lowest-latency cost signal: statement_scanned_bytes_billed (DELTA, ~3 minute publish delay).
// Capacity (Editions) projects are billed for slots, not bytes, and normally report ~0 here.
| WHERE resource.attributes.gcp.resource_type == "bigquery_project"
  // Read only the series this rule uses (bytes billed plus the two heartbeat metrics)
  AND (`metrics.bigquery.googleapis.com/query/statement_scanned_bytes_billed` IS NOT NULL
    OR `metrics.bigquery.googleapis.com/query/count` IS NOT NULL
    OR `metrics.bigquery.googleapis.com/job/num_in_flight` IS NOT NULL)
// Stage 1: bytes billed per project per minute. DELTA amounts are additive, so SUM is exact
// across fragmented TSIDs, locations, priorities and statement types.
// `heartbeat` counts query/count and job/num_in_flight samples, which GCP reports every minute
// (as 0 when idle). A minute counts as published only when heartbeat > 0.
| STATS billed = SUM(SUM_OVER_TIME(`metrics.bigquery.googleapis.com/query/statement_scanned_bytes_billed`)),
        heartbeat = SUM(COUNT_OVER_TIME(`metrics.bigquery.googleapis.com/query/count`)) + SUM(COUNT_OVER_TIME(`metrics.bigquery.googleapis.com/job/num_in_flight`))
    BY @timestamp = TBUCKET(1 minute), resource.attributes.project_id
| EVAL billed = COALESCE(billed, 0)
// Comparison periods, relative to rule execution time. They are explicit, so a look-back longer
// than the required 25h35m (NOW() - 1535 minutes) changes nothing; a shorter one disables the rule.
//   recent    = the last full hour, ending 5 minutes ago (skips not-yet-published minutes)
//   baseline  = the 24 hours before the recent hour (hourly average)
//   yesterday = 24 hours earlier, widened by 30 minutes on each side (2 hours), so a daily scheduled job
//               that runs a little earlier or later than yesterday is still found. The reference is the
//               largest of three overlapping 1-hour slices of that window (early, aligned, late), so it
//               stays an hourly figure comparable with the recent hour.
| EVAL period = CASE(
    @timestamp >= NOW() - 65 minutes AND @timestamp < NOW() - 5 minutes, "recent",
    @timestamp >= NOW() - 1505 minutes AND @timestamp < NOW() - 65 minutes, "baseline",
    "other")
| EVAL yesterday_window = @timestamp >= NOW() - 1535 minutes AND @timestamp < NOW() - 1415 minutes
| STATS recent_bytes_billed = SUM(billed) WHERE period == "recent",
        baseline_bytes_billed = SUM(billed) WHERE period == "baseline",
        yesterday_early_bytes = SUM(billed) WHERE @timestamp >= NOW() - 1535 minutes AND @timestamp < NOW() - 1475 minutes,
        yesterday_aligned_bytes = SUM(billed) WHERE @timestamp >= NOW() - 1505 minutes AND @timestamp < NOW() - 1445 minutes,
        yesterday_late_bytes = SUM(billed) WHERE @timestamp >= NOW() - 1475 minutes AND @timestamp < NOW() - 1415 minutes,
        // Published minutes per period (heartbeat > 0; this also keeps heartbeat referenced,
        // otherwise ES|QL prunes it and silently drops the minutes without billing)
        recent_minutes = COUNT(*) WHERE period == "recent" AND heartbeat > 0,
        baseline_minutes = COUNT(*) WHERE period == "baseline" AND heartbeat > 0,
        yesterday_minutes = COUNT(*) WHERE yesterday_window AND heartbeat > 0
    BY resource.attributes.project_id

breach.segment:
// Customise: data coverage required before comparing. A collector or publishing gap must not
// shrink the reference: recent >= 45 of 60 minutes, baseline >= 1200 of 1440 minutes
// (~83%, so a new project needs ~a day of history), and the yesterday window complete (120 of 120).
// Bytes billed are reported only in minutes that billed, so a single missing minute yesterday can hide
// a daily job and make today's identical run look like a spike.
WHERE recent_minutes >= 45 AND baseline_minutes >= 1200 AND yesterday_minutes >= 120
// Hourly average over published baseline minutes only (not elapsed time)
| EVAL baseline_hourly_bytes = COALESCE(baseline_bytes_billed, 0) * 60.0 / baseline_minutes,
       yesterday_bytes_billed = GREATEST(COALESCE(yesterday_early_bytes, 0), COALESCE(yesterday_aligned_bytes, 0), COALESCE(yesterday_late_bytes, 0)),
       recent_bytes_billed = COALESCE(recent_bytes_billed, 0)
| EVAL reference_bytes = GREATEST(baseline_hourly_bytes, yesterday_bytes_billed)
// Customise: minimum spend worth alerting on (default 1 TiB billed in the hour)
| WHERE recent_bytes_billed >= 1099511627776
// Customise: spike multiplier versus the larger of the 24h hourly average and the yesterday window
| WHERE recent_bytes_billed >= 3 * reference_bytes
| EVAL recent_tib_billed = ROUND(recent_bytes_billed / 1099511627776.0, 2),
       reference_tib_billed = ROUND(reference_bytes / 1099511627776.0, 2),
       spike_ratio = CASE(reference_bytes > 0, ROUND(recent_bytes_billed / reference_bytes, 1), NULL)
| KEEP resource.attributes.project_id, recent_tib_billed, reference_tib_billed, spike_ratio, recent_bytes_billed, baseline_hourly_bytes, yesterday_bytes_billed, recent_minutes, baseline_minutes, yesterday_minutes
| SORT recent_bytes_billed DESC
| LIMIT 50
